<?php
 declare(strict_types=1); namespace Nyholm\Psr7; use Psr\Http\Message\{RequestInterface, StreamInterface, UriInterface}; final class Request implements RequestInterface { use MessageTrait; use RequestTrait; public function __construct(string $method, $uri, array $headers = [], $body = null, string $version = '1.1') { if (!($uri instanceof UriInterface)) { $uri = new Uri($uri); } $this->method = $method; $this->uri = $uri; $this->setHeaders($headers); $this->protocol = $version; if (!$this->hasHeader('Host')) { $this->updateHostFromUri(); } if ('' !== $body && null !== $body) { $this->stream = Stream::create($body); } } } 